<div class="page-actions"><a class="back-link" href="<?= site_url('admin/koperasi/'.$coop['id']) ?>">← Profil koperasi</a><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/koperasi/'.$coop['id'].'/unit/tambah') ?>">+ Tambah unit</a><?php endif; ?></div>
<div class="intro-line"><p>Unit USP/USPPS yang aktif dapat dipilih saat memulai penilaian kesehatan. Arsip unit tidak menghapus riwayat penilaian.</p></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari unit</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama atau nomor izin"></label><label><span>Status</span><select name="status"><option value="">Semua</option><option value="aktif" <?= $p['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="arsip" <?= $p['status']==='arsip'?'selected':'' ?>>Arsip</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Unit usaha</th><th>Jenis</th><th>Nomor izin</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $unit): ?><tr><td><strong><?= h($unit['name']) ?></strong><small class="cell-sub"><?= h($unit['address']?:'Alamat belum diisi') ?></small></td><td><?= h($unit['type_name']) ?></td><td><?= h($unit['license_number']?:'—') ?></td><td><span class="pill <?= $unit['active']?'pill-green':'pill-muted' ?>"><?= $unit['active']?'Aktif':'Arsip' ?></span></td><td class="actions-cell"><?php if ($can_edit): ?><a class="row-link" href="<?= site_url('admin/koperasi/'.$coop['id'].'/unit/'.$unit['id'].'/ubah') ?>">Ubah</a><?php endif; ?><?php if ($can_archive): ?><form method="post" action="<?= site_url('admin/koperasi/'.$coop['id'].'/unit/'.$unit['id'].'/status') ?>" onsubmit="return confirm('Ubah status unit ini?')"><?= csrf_input() ?><button class="text-button" type="submit"><?= $unit['active']?'Arsipkan':'Aktifkan' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty-cell">Belum ada unit sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
